BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();key uuid;link uuid;r jsonb;asset jsonb;other jsonb;settings jsonb;lease jsonb;first_id uuid;candidate integer;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(outsider);INSERT INTO public.user_roles VALUES(actor,'admin');
 r:=public.redirect_management_mutate('[{"operation":"create","data":{"target":"/private-target"}}]');link:=(r#>>'{0,link,id}')::uuid;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,redirect_ids,created_by,expires_at) VALUES('Artwork key',repeat('e',64),'fixture',ARRAY['links:read'],ARRAY[link],actor,now()+interval '1 day') RETURNING id INTO key;
 settings:=public.redirect_qr_style_resource(actor);
 r:=public.redirect_qr_image_resource('create',actor,p_values=>jsonb_build_object('linkId',link,'logoMode','custom'),p_hash=>repeat('a',64));
 IF r->>'state'<>'pending' OR public.redirect_public_qr_image(repeat('a',64)) IS NOT NULL THEN RAISE EXCEPTION 'Draft became public before artwork';END IF;
 BEGIN PERFORM public.reserve_redirect_qr_image_logo(outsider,NULL,(r->>'id')::uuid,(r->>'version')::uuid,'image/png',100,64,64,repeat('f',64));RAISE EXCEPTION 'Outsider reserved artwork';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.reserve_redirect_qr_image_logo(actor,NULL,(r->>'id')::uuid,gen_random_uuid(),'image/png',100,64,64,repeat('f',64));RAISE EXCEPTION 'Stale version reserved artwork';EXCEPTION WHEN unique_violation THEN NULL;END;
 asset:=public.reserve_redirect_qr_image_logo(actor,NULL,(r->>'id')::uuid,(r->>'version')::uuid,'image/png',100,64,64,repeat('f',64));first_id:=(asset->>'id')::uuid;
 IF asset#>>'{profile,url}' NOT LIKE 'https://queer.guide/go/%' OR asset::text LIKE '%private-target%' THEN RAISE EXCEPTION 'Reservation lost canonical URL or exposed destination';END IF;
 BEGIN PERFORM public.finish_redirect_qr_logo(actor,first_id);RAISE EXCEPTION 'Image artwork altered workspace defaults';EXCEPTION WHEN no_data_found THEN NULL;END;
 r:=public.finish_redirect_qr_image_logo(actor,NULL,(r->>'id')::uuid,first_id);
 IF r->>'state'<>'published' OR r#>>'{logoAsset,id}'<>first_id::text OR public.redirect_public_qr_image(repeat('a',64))->>'logoSource'<>'custom' OR public.redirect_qr_style_resource(actor)<>settings THEN RAISE EXCEPTION 'Custom publication not isolated from workspace branding';END IF;
 BEGIN PERFORM public.finish_redirect_qr_image_logo(actor,NULL,(r->>'id')::uuid,first_id);RAISE EXCEPTION 'Consumed artwork reservation reused';EXCEPTION WHEN no_data_found THEN NULL;END;
 UPDATE public.redirect_qr_assets SET next_cleanup_at=now()-interval '1 second' WHERE id=first_id;
 IF public.claim_redirect_qr_asset_cleanup(5)<>'[]' THEN RAISE EXCEPTION 'Referenced image artwork claimed for cleanup';END IF;
 PERFORM public.redirect_qr_image_resource('revoke',actor,p_id=>(r->>'id')::uuid,p_values=>jsonb_build_object('version',r->>'version'));
 IF public.redirect_public_qr_image(repeat('a',64)) IS NOT NULL OR (SELECT logo_asset_id FROM public.redirect_qr_image_links WHERE id=(r->>'id')::uuid) IS NOT NULL OR (SELECT next_cleanup_at FROM public.redirect_qr_assets WHERE id=first_id)<now()+interval '59 minutes' THEN RAISE EXCEPTION 'Revocation failed to release artwork with grace';END IF;
 UPDATE public.redirect_qr_assets SET next_cleanup_at=now()-interval '1 second' WHERE id=first_id;
 lease:=public.claim_redirect_qr_asset_cleanup(5);
 IF jsonb_array_length(lease)<>1 OR lease#>>'{0,id}'<>first_id::text OR NOT public.finish_redirect_qr_asset_cleanup(first_id,(lease#>>'{0,lease}')::uuid,true) THEN RAISE EXCEPTION 'Released artwork cleanup failed';END IF;
 r:=public.redirect_qr_image_resource('create',p_principal=>key,p_values=>jsonb_build_object('linkId',link,'logoMode','custom'),p_hash=>repeat('b',64));
 asset:=public.reserve_redirect_qr_image_logo(NULL,key,(r->>'id')::uuid,(r->>'version')::uuid,'image/jpeg',100,64,64,repeat('c',64));
 UPDATE public.redirect_api_tokens SET revoked_at=now() WHERE id=key;
 BEGIN PERFORM public.finish_redirect_qr_image_logo(NULL,key,(r->>'id')::uuid,(asset->>'id')::uuid);RAISE EXCEPTION 'Revoked key attached uploaded bytes';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE public.redirect_api_tokens SET revoked_at=NULL WHERE id=key;
 UPDATE public.redirect_qr_image_links SET version=gen_random_uuid() WHERE id=(r->>'id')::uuid;
 BEGIN PERFORM public.finish_redirect_qr_image_logo(NULL,key,(r->>'id')::uuid,(asset->>'id')::uuid);RAISE EXCEPTION 'Stale draft accepted uploaded bytes';EXCEPTION WHEN unique_violation THEN NULL;END;
 UPDATE public.redirect_qr_image_links SET draft_expires_at=now()-interval '2 days' WHERE id=(r->>'id')::uuid;
 BEGIN PERFORM public.reserve_redirect_qr_image_logo(NULL,key,(r->>'id')::uuid,(r->>'version')::uuid,'image/png',100,64,64,repeat('f',64));RAISE EXCEPTION 'Expired draft accepted reservation';EXCEPTION WHEN no_data_found THEN NULL;END;
 PERFORM public.prune_redirect_qr_image_history(1000);
 IF EXISTS(SELECT FROM public.redirect_qr_image_links WHERE id=(r->>'id')::uuid) OR (SELECT qr_image_id FROM public.redirect_qr_assets WHERE id=(asset->>'id')::uuid) IS NOT NULL THEN RAISE EXCEPTION 'Expired draft retained references';END IF;
 UPDATE public.redirect_qr_assets SET expires_at=now()-interval '1 second',next_cleanup_at=now()-interval '1 second' WHERE id=(asset->>'id')::uuid;
 IF jsonb_array_length(public.claim_redirect_qr_asset_cleanup(5))<>1 THEN RAISE EXCEPTION 'Deleted draft lost tracked orphan cleanup';END IF;
 r:=public.redirect_qr_image_resource('create',actor,p_values=>jsonb_build_object('linkId',link,'logoMode','custom'),p_hash=>repeat('d',64));
 FOR candidate IN 1..3 LOOP
  asset:=public.reserve_redirect_qr_image_logo(actor,NULL,(r->>'id')::uuid,(r->>'version')::uuid,'image/png',100,64,64,repeat('f',64));
 END LOOP;
 IF public.reserve_redirect_qr_image_logo(actor,NULL,(r->>'id')::uuid,(r->>'version')::uuid,'image/png',100,64,64,repeat('f',64))->>'retryAfter'<>'900' THEN RAISE EXCEPTION 'Pending artwork reservation budget ignored';END IF;
 r:=public.finish_redirect_qr_image_logo(actor,NULL,(r->>'id')::uuid,(asset->>'id')::uuid);
 DELETE FROM public.redirects WHERE id=link;
 IF (SELECT qr_image_id FROM public.redirect_qr_assets WHERE id=(asset->>'id')::uuid) IS NOT NULL OR (SELECT next_cleanup_at FROM public.redirect_qr_assets WHERE id=(asset->>'id')::uuid)<now()+interval '59 minutes' THEN RAISE EXCEPTION 'Link deletion lost artwork cleanup grace';END IF;
 IF has_function_privilege('anon','public.finish_redirect_qr_image_logo(uuid,uuid,uuid,uuid)','execute') THEN RAISE EXCEPTION 'Private artwork completion exposed';END IF;
END $$;
ROLLBACK;
